import { useThree, useFrame } from '@react-three/fiber'
import { useEffect, useRef } from 'react'
import * as THREE from 'three'

export type CamSpec = {
  az: number
  el: number
  dist: number
  target: [number, number, number]
  fov: number
}

/**
 * Камера, управляемая query-параметрами — чтобы рендерить кадры по сценарию:
 *   ?az=45&el=12&dist=9&ty=1.2&fov=40
 * Позволяет снимать одни и те же ракурсы детерминированно (для видео).
 */
function readSpec(): CamSpec {
  const q = new URLSearchParams(location.search)
  const n = (k: string, d: number) => {
    const v = parseFloat(q.get(k) ?? '')
    return Number.isFinite(v) ? v : d
  }
  return {
    az: n('az', 28),
    el: n('el', 10),
    dist: n('dist', 11),
    target: [n('tx', 0), n('ty', 1.4), n('tz', 0)],
    fov: n('fov', 42),
  }
}

export function useCamSpec() {
  return useRef<CamSpec>(readSpec())
}

export function CameraRig({ enabled = true }: { enabled?: boolean }) {
  const { camera } = useThree()
  const spec = useRef<CamSpec>(readSpec())
  const applied = useRef(false)

  useEffect(() => {
    const cam = camera as THREE.PerspectiveCamera
    cam.fov = spec.current.fov
    cam.updateProjectionMatrix()
  }, [camera])

  useFrame(({ gl }) => {
    if (!enabled || applied.current) return
    applied.current = true
    const { az, el, dist, target } = spec.current
    const a = THREE.MathUtils.degToRad(az)
    const e = THREE.MathUtils.degToRad(el)
    const x = target[0] + dist * Math.cos(e) * Math.sin(a)
    const y = target[1] + dist * Math.sin(e)
    const z = target[2] + dist * Math.cos(e) * Math.cos(a)
    camera.position.set(x, y, z)
    camera.lookAt(target[0], target[1], target[2])
    const d = new THREE.Vector3()
    camera.getWorldDirection(d)
    document.title = `CAM pos=${camera.position.toArray().map((n) => n.toFixed(1))} dir=${d
      .toArray()
      .map((n) => n.toFixed(2))} drawCalls=${gl.info.render.calls} tris=${gl.info.render.triangles}`
  })

  return null
}

import { useGLTF, useAnimations } from '@react-three/drei'
import { useEffect, useMemo, useRef } from 'react'
import * as THREE from 'three'
import { useFrame } from '@react-three/fiber'


/**
 * Персонаж из Blender (glTF со скелетом и клипами).
 * Управляется параметрами URL для покадрового рендера:
 *   ?model=1&clip=Walk&t=0.35   — поставить позу на 35% клипа
 */
export function Detective({
  clip = 'Idle',
  time = 0,
  position = [0, 0, 0],
  rotationY = 0,
  scale = 1,
}: {
  clip?: string
  time?: number
  position?: [number, number, number]
  rotationY?: number
  scale?: number
}) {
  const { scene, animations } = useGLTF('/models/detective.glb')
  const { actions, names } = useAnimations(animations, scene)
  const group = useRef<THREE.Group>(null)

  const cloned = useMemo(() => {
    const s = scene.clone(true)
    s.traverse((o) => {
      const m = o as THREE.Mesh
      if (m.isMesh) {
        m.castShadow = true
        m.receiveShadow = true
        m.frustumCulled = false
        const mats = Array.isArray(m.material) ? m.material : [m.material]
        mats.forEach((mat) => {
          const mm = mat as THREE.MeshStandardMaterial
          if (mm && 'roughness' in mm) {
            mm.envMapIntensity = 0.9
          }
        })
      }
    })
    return s
  }, [scene])

  useEffect(() => {
    const act = actions[clip] ?? actions[names[0]]
    if (!act) return
    act.reset()
    act.setLoop(THREE.LoopRepeat, Infinity)
    act.play()
    act.paused = true
    act.time = time
  }, [actions, names, clip, time, cloned])

  // держим точку по времени параметра (детерминированно для рендера)
  useFrame(() => {
    const act = actions[clip]
    if (act) {
      act.paused = true
      act.time = time
    }
  })

  return (
    <group ref={group} position={position} rotation={[0, rotationY, 0]} scale={scale}>
      <primitive object={cloned} />
    </group>
  )
}

