import { useGLTF, useAnimations } from '@react-three/drei'
import { useEffect, useMemo } from 'react'
import { useFrame } from '@react-three/fiber'
import * as THREE from 'three'

/**
 * Ригнутая glTF-модель с детерминированной позой: клип ставится на паузу и
 * держится на времени из параметров URL, чтобы кадры рендерились покадрово
 * (видео клипов не «плывут» между прогонами).
 *
 *   ?clip=Walk&t=0.35
 *
 * Геометрия клонируется, чтобы несколько копий модели в одной сцене не делили
 * скелет: анимации ведутся на клоне, тени и frustum выставляются явно.
 */
export function GltfModel({
  src,
  clip = 'Idle',
  time = 0,
  position = [0, 0, 0],
  rotationY = 0,
  scale = 1,
  envMapIntensity = 0.9,
}: {
  src: string
  clip?: string
  time?: number
  position?: [number, number, number]
  rotationY?: number
  scale?: number
  envMapIntensity?: number
}) {
  const { scene, animations } = useGLTF(src)
  const { actions, names } = useAnimations(animations, scene)

  const cloned = useMemo(() => {
    const s = scene.clone(true)
    s.traverse((o) => {
      const m = o as THREE.Mesh
      if (m.isMesh) {
        m.castShadow = true
        m.receiveShadow = true
        m.frustumCulled = false
        const mats = Array.isArray(m.material) ? m.material : [m.material]
        mats.forEach((mat) => {
          const mm = mat as THREE.MeshStandardMaterial
          if (mm && 'roughness' in mm) {
            mm.envMapIntensity = envMapIntensity
          }
        })
      }
    })
    return s
  }, [scene, envMapIntensity])

  useEffect(() => {
    const act = actions[clip] ?? actions[names[0]]
    if (!act) return
    act.reset()
    act.setLoop(THREE.LoopRepeat, Infinity)
    act.play()
    act.paused = true
    act.time = time
  }, [actions, names, clip, time, cloned])

  // держим точку по времени параметра (детерминированно для рендера)
  useFrame(() => {
    const act = actions[clip]
    if (act) {
      act.paused = true
      act.time = time
    }
  })

  return (
    <group position={position} rotation={[0, rotationY, 0]} scale={scale}>
      <primitive object={cloned} />
    </group>
  )
}

import { Grid } from '@react-three/drei'

/**
 * Студийный стенд: холодный ключ + тёплая заливка сбоку, синяя контровая,
 * пол-сетка для ощущения масшташа. Общий для режимов `scene=model`
 * (персонаж) и `scene=props` (транспорт, окружение).
 */
export function Studio({
  shadowRange = 3,
  shadowMap = 1536,
  floor = 6,
  gridCell = 0.25,
}: {
  /** половина стороны теневой камеры, м */
  shadowRange?: number
  shadowMap?: number
  /** сторона пола-сетки в метрах, 0 — без пола */
  floor?: number
  gridCell?: number
}) {
  return (
    <>
      <color attach="background" args={['#0b0e15']} />
      <ambientLight intensity={0.6} color="#7f9ad0" />
      <hemisphereLight args={['#a8c0ea', '#20222c', 0.9]} />
      <directionalLight
        castShadow
        position={[-3, 5, 4]}
        intensity={2.2}
        color="#e8eeff"
        shadow-mapSize={[shadowMap, shadowMap]}
        shadow-camera-near={0.5}
        shadow-camera-far={shadowRange * 6}
        shadow-camera-left={-shadowRange}
        shadow-camera-right={shadowRange}
        shadow-camera-top={shadowRange}
        shadow-camera-bottom={-shadowRange}
        shadow-bias={-0.0004}
        shadow-normalBias={0.02}
      />
      {/* ключ сбоку, чтобы читался объём */}
      <directionalLight position={[4, 2.5, -3]} intensity={0.9} color="#ffb877" />
      <directionalLight position={[0, 1.2, -5]} intensity={0.7} color="#5ad6ff" />

      {floor > 0 && (
        <>
          <mesh rotation={[-Math.PI / 2, 0, 0]} receiveShadow position={[0, 0, 0]}>
            <circleGeometry args={[floor / 2, 64]} />
            <meshStandardMaterial color="#14161d" roughness={0.85} metalness={0.05} />
          </mesh>
          <Grid
            args={[floor, floor]}
            cellSize={gridCell}
            cellColor="#2a3040"
            sectionSize={gridCell * 4}
            sectionColor="#3d4759"
            fadeDistance={floor * 1.2}
            position={[0, 0.002, 0]}
          />
        </>
      )}
    </>
  )
}

import { useGLTF } from '@react-three/drei'
import { useMemo } from 'react'
import * as THREE from 'three'
import { GltfModel } from './GltfModel'
import { Studio } from './Studio'
import { CameraRig } from './CameraRig'
import { ProceduralEnv } from './ProceduralEnv'
import { RenderProbe } from './RenderProbe'

/**
 * Стенд для моделей из tools/: транспорт и набор уличного реквизита.
 *
 *   ?scene=props&prop=car|tram|kit&clip=Drive&t=0.4
 *
 * Камера кадрирует модель автоматически по bounding box (в стенде масштаб
 * разный: седан 4.5 м, трамвай 14 м, кит — россыпь на 30 м), но любой
 * параметр камеры из URL всё равно главнее: ?dist=6&ty=1.0.
 */
const PROPS = {
  car: { src: '/models/car.glb', clips: ['Drive', 'Idle', 'Siren'], floor: 24, cell: 1 },
  tram: { src: '/models/tram.glb', clips: ['Run'], floor: 32, cell: 2 },
  kit: { src: '/models/street_kit.glb', clips: ['Wind'], floor: 48, cell: 2 },
} as const

export type PropName = keyof typeof PROPS

export function Props({
  name,
  clip,
  time = 0,
  probe = false,
}: {
  name: string
  clip?: string
  time?: number
  probe?: boolean
}) {
  const prop = PROPS[name as PropName] ?? PROPS.car
  const active = prop.clips.includes(clip as never) ? clip : prop.clips[0]
  return (
    <>
      <Studio shadowRange={14} shadowMap={2048} floor={prop.floor} gridCell={prop.cell} />
      <Framed src={prop.src} clip={active} time={time} />
      <ProceduralEnv intensity={1.0} />
      <RenderProbe probe={probe} />
    </>
  )
}

function Framed({ src, clip, time }: { src: string; clip: string; time: number }) {
  // useGLTF кэширует загрузку, поэтому bbox берётся из того же объекта,
  // который потом клонирует GltfModel, — без второй загрузки.
  const { scene } = useGLTF(src)
  const frame = useMemo(() => {
    const box = new THREE.Box3().setFromObject(scene)
    const c = box.getCenter(new THREE.Vector3())
    const size = box.getSize(new THREE.Vector3())
    return { target: [c.x, c.y, c.z] as [number, number, number], radius: size.length() / 2 }
  }, [scene])

  return (
    <>
      <GltfModel src={src} clip={clip} time={time} />
      <CameraRig frame={frame} />
    </>
  )
}

